local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[409601]=b({e[25033],409601,false,178,422,false,200096,false,"deco/character/feiming",302002,60,false,false,false,false,-120,"1",false,false,false,false,false,false,false,"0,380,0.93","0,-40,1",1813,833,390,1312,741,1222,3038,1312,741,1222,1047},h)g[409602]=b({e[24034],409602,1,4,423,"「ええ酒はあらへんけど、こないな月夜にぴったりなお茶なら、ええもんがありますよ。\n……なんや、えらい嬉しそうやって？　……まぁ、そうかもしれへんなあ。\nお茶も景色も、一緒に味わう人がおってこそ、えも言われぬ風情を感じられるんやろうなあ。」",200096,1,"deco/character/feiming_0",302002,60,false,false,false,false,false,"1",false,"0,540,0.95","-50,540,0.95",false,"-50,540,0.95","-50,540,0.95","50,520,0.95",1825,1397,390,534,307,2799,3691,534,1091,2799,1261},h)g[409701]=b({e[17057],409701,false,179,424,false,200097,false,"deco/character/sataen",302002,60,false,false,false,false,false,"1","sataen"},h)g[409702]=b({e[17057],409702,1,4,425,"「この銃創は、奴らからのメッセージだ。『死にかけの信者は、いくら敬虔であっても神の捨て駒に過ぎない。』\n……今は、私が北国全体をチェスボードにする番だ。キングにチェックメイトをかけるに最も効果的なやり方、それは攻め続けることではなく、相手に自分がすべてを掌握していると勘違いさせること。\nそうだ、次の手は君の判断に任せよう。氷山を切り崩す決めの一手にしてみせるよ」",200097,1,"deco/character/sataen_0",302002,60,false,false,false,false,false,"1","sataen_0"},h)g[409703]=b({e[9057],409703,12,180,426,"「輝く宝石はこれまで数え切れぬほど見てきたが、光が君を照らした瞬間思ったよ、やっと手にしたい一粒を見つけた、とね。\nさぁ、こちらまで来なさい。頂から見る景色こそ、あなたのその輝きにふさわしい。」",200097,2,"deco/character/sataen_LF","sataen_lf"},h)g[409801]=b({e[46057],409801,false,181,427,false,200098,false,"deco/character/huayuqing",302002,60,false,false,false,false,false,"1",false,"0,-10,1","0,-10,1",false,"0,-10,1","0,-10,1","0,-10,1","0,40,1",false,false,false,false,false,"-20,-50,1","-20,-50,1",false,false,"-20,-70,1",1833,834,390,1038,737,1658,2569,1038,737,1658,1052,"huayuqing"},h)g[409802]=b({e[23034],409802,1,4,428,"「はーやーくー！ せっかくお姉ちゃんを説得して、あなたにお化粧してもらえることになったのにー。もたもたしてたら開演時間になっちゃうよ！\nえっ、この前は上手くできなかったから自信がない？\nもー、数をこなして慣れるしかないし、こういう機会には目一杯やらなきゃ！\nそれに、あなたが一生懸命わたしに化粧してる時の顔、すっごく好きだから、もっとたくさん見たいしね♪」",200098,1,"deco/character/huayuqing_0",302002,60,false,false,1,false,false,"1",false,false,"-340,0,1",false,"-340,0,1","-340,0,1",2385,987,390,746,873,2328,2014,746,873,2328,1069,false,false,false,false,false,false,false,false,false,false,false,false,"huayuqing_0"},h)g[409803]=b({e[9045],409803,12,180,429,"「おや～、そこのお客さん？ 怪盗の正体は、絶対にバレちゃいけない秘密なんだ～。\nこうなったらわたしと共犯になるか、今夜の月明かりに消えてもらうしかないね～？\n……なーんてねっ、くすくすっ。\n全部演技だし、そう緊張しないでってば。今日は新作の劇のインスピレーションを得るために、ゲスト出演してるだけなの。\nさて、そろそろ戻るから、わたしの活躍、よ～～く目に焼き付けてね！」",200098,2,"deco/character/huayuqing_LF",1,4206,5000,2160,2472,3000,10300,10600,6533,14917,8000,3000,"huayuqing_lf"},h)g[409901]=b({e[46057],409901,false,182,430,false,200099,false,"deco/character/huayubai",302002,60,false,false,false,false,-30,"1",false,"0,-10,1","0,-10,1",false,"0,-10,1","0,-10,1","-140,-10,1","0,50,1","-190,-20,1","-140,-20,1",false,false,"-170,-20,1","-180,-60,1","-180,-60,1",false,false,"-170,-90,1",1989,818,390,1015,721,1985,2605,1015,721,1985,1052,"huayubai"},h)g[409902]=b({e[46057],409902,1,4,431,"「今日は化粧班に欠員が出てしまって、君まで駆り出す事態になってしまったわ。本当にごめんなさい。\n私はもうすぐ出来上がるけど、そうね……腰の帯を締めていただけるかしら。\nあ、そうだ、口紅がまだだったわね。もしよかったら、後でお願いしても良いかしら？」",200099,1,"deco/character/huayubai_0",302002,60,false,false,false,false,false,"1",false,"50,0,1",false,false,false,false,"0,40,1",false,false,false,false,false,false,false,false,false,false,false,1676,994,390,646,464,2654,2510,646,688,2654,1261,"huayubai_0"},h)g[409903]=b({e[9045],409903,12,180,432,"「あなたが付き添いを引き受けてくださったおかげで、このどうしても断りきれなかった立食パーティーも、多少気が楽になりました。\n……とはいえ、今のような二人きりの方が、やはり居心地がいいものですね。\n静かに過ごすこの時間は、お芝居のハッピーエンドよりも……ずっと、真実味がありますから。」",200099,2,"deco/character/huayubai_LF",1,3938,5000,1850,3905,5333,8166,9333,8666,14067,8000,2666,"huayubai_lf"},h)